patched:
Active_gNBs = ( "gNB-MAA-002");
# Asn1_verbosity, choice in: none, info, annoying
Asn1_verbosity = "none";

security = {

  # preferred ciphering algorithms
  # the first one of the list that an UE supports in chosen
  # valid values: nea0, nea1, nea2, nea3
  ciphering_algorithms = ( "nea2", "nea1" );

  # preferred integrity algorithms
  # the first one of the list that an UE supports in chosen
  # valid values: nia0, nia1, nia2, nia3
  integrity_algorithms = ( "nia2", "nia1" );

  # setting 'drb_ciphering' to "no" disables ciphering for DRBs, no matter
  # what 'ciphering_algorithms' configures; same thing for 'drb_integrity'
  drb_ciphering = "yes";
  drb_integrity = "yes";
};

# sectwin extension: interface protection settings (not part of upstream OAI)
interface_security = {

  f1c_protection  = "dtls";   # dtls | ipsec | none
  n2_protection   = "ipsec";   # dtls | ipsec | none
  n3_protection   = "ipsec";   # ipsec | none
  xn_protection   = "ipsec";   # dtls | ipsec | none
  e2_protection   = "ipsec";   # ipsec | none
  o1_transport    = "netconf_tls";   # netconf_ssh | netconf_tls | netconf_plain
  tls_min_version = "1.3";   # 1.0 | 1.1 | 1.2 | 1.3
};

gNBs =
(
 {
    ////////// Identification parameters:
    gNB_ID    =  0xE02;
    gNB_name  =  "gNB-MAA-002";

    // Tracking area code, 0x0000 and 0xfffe are reserved values
    tracking_area_code  =  6;
    plmn_list = ({ mcc = 208; mnc = 99; mnc_length = 2; snssaiList = ({ sst = 1; }) });

    nr_cellid = 12345032L;

    ////////// Physical parameters:
    min_rxtxtime = 6;

    servingCellConfigCommon = (
    {
 #spCellConfigCommon
      physCellId                                                    = 588;
#  downlinkConfigCommon
    #frequencyInfoDL
      # this is 3600 MHz + 43 PRBs@30kHz SCS (same as initial BWP)
      absoluteFrequencySSB                                          = 641640;
      dl_frequencyBand                                              = 78;
      # this is 3600 MHz
      dl_absoluteFrequencyPointA                                    = 641280;
      #scs-SpecificCarrierList
        dl_offstToCarrier                                           = 0;
# subcarrierSpacing
# 0=kHz15, 1=kHz30, 2=kHz60, 3=kHz120
        dl_subcarrierSpacing                                        = 1;
        dl_carrierBandwidth                                         = 106;
      ssb_periodicityServingCell                                    = 2;
      dmrs_TypeA_Position                                           = 0;
      subcarrierSpacing                                             = 1;
      ssPBCH_BlockPower                                             = -25;
    }
  );

    ////////// AMF parameters:
    amf_ip_address = ({ ipv4 = "10.43.0.128"; });

    NETWORK_INTERFACES :
    {
        GNB_IPV4_ADDRESS_FOR_NG_AMF              = "10.82.229.75/24";
        GNB_IPV4_ADDRESS_FOR_NGU                 = "10.82.229.75/24";
        GNB_PORT_FOR_S1U                         = 2152; # Spec 2152
    };
 }
);

MACRLCs = (
  {
    num_cc                      = 1;
    tr_s_preference             = "local_L1";
    tr_n_preference             = "local_RRC";
    pusch_TargetSNRx10          = 150;
    pucch_TargetSNRx10          = 200;
  }
);

L1s = (
  {
    num_cc = 1;
    tr_n_preference = "local_mac";
    prach_dtx_threshold = 120;
    pucch0_dtx_threshold = 150;
    ofdm_offset_divisor = 8; #set this to UINT_MAX for offset 0
  }
);

log_config :
{
  global_log_level                      ="info";
  hw_log_level                          ="info";
  phy_log_level                         ="info";
  mac_log_level                         ="info";
  rlc_log_level                         ="info";
  pdcp_log_level                        ="info";
  rrc_log_level                         ="info";
  ngap_log_level                        ="debug";
  f1ap_log_level                        ="debug";
};

